// Included by every C file generated by tools/ws7/recomp/xlat: register
// fill/spill macros and the helper headers.
#ifndef RC_GEN_H
#define RC_GEN_H
#include "rc.h"
#include "rc_int.h"
#include "rc_sse.h"
#include "rc_call.h"
// the wrappers of hook points (gen_image.py `wrap`, rc_hook.h)
void rc_hook_call(int index, rc_ctx *c, rc_fn orig);
#pragma clang diagnostic ignored "-Wunused-label"
#pragma clang diagnostic ignored "-Wunused-variable"
#pragma clang diagnostic ignored "-Wunused-but-set-variable"
#pragma clang diagnostic ignored "-Wparentheses-equality"

// Function-entry tracing (xlat with RC_EMIT_TRACE=1, compiled -DRC_TRACE; the build must then
// provide rc_trace_enter).
#ifdef RC_TRACE
void rc_trace_enter(uint64_t addr);
#define RC_ENTER(a) rc_trace_enter(a)
#else
#define RC_ENTER(a) ((void)0)
#endif

#define XFILL_DECL() rc_v128 x0 = c->x[0], x1 = c->x[1], x2 = c->x[2], x3 = c->x[3], x4 = c->x[4], \
  x5 = c->x[5], x6 = c->x[6], x7 = c->x[7], x8 = c->x[8], x9 = c->x[9], x10 = c->x[10], \
  x11 = c->x[11], x12 = c->x[12], x13 = c->x[13], x14 = c->x[14], x15 = c->x[15]
#define XFILL() do { x0 = c->x[0]; x1 = c->x[1]; x2 = c->x[2]; x3 = c->x[3]; x4 = c->x[4]; \
  x5 = c->x[5]; x6 = c->x[6]; x7 = c->x[7]; x8 = c->x[8]; x9 = c->x[9]; x10 = c->x[10]; \
  x11 = c->x[11]; x12 = c->x[12]; x13 = c->x[13]; x14 = c->x[14]; x15 = c->x[15]; } while (0)
#define XSPILL() do { c->x[0] = x0; c->x[1] = x1; c->x[2] = x2; c->x[3] = x3; c->x[4] = x4; \
  c->x[5] = x5; c->x[6] = x6; c->x[7] = x7; c->x[8] = x8; c->x[9] = x9; c->x[10] = x10; \
  c->x[11] = x11; c->x[12] = x12; c->x[13] = x13; c->x[14] = x14; c->x[15] = x15; } while (0)
#define FILL_DECL() XFILL_DECL(); uint64_t rax = c->r[0], rcx = c->r[1], rdx = c->r[2], rbx = c->r[3], \
  rsp = c->r[4], rbp = c->r[5], rsi = c->r[6], rdi = c->r[7], r8 = c->r[8], r9 = c->r[9], \
  r10 = c->r[10], r11 = c->r[11], r12 = c->r[12], r13 = c->r[13], r14 = c->r[14], r15 = c->r[15]
#define FILL() do { rax = c->r[0]; rcx = c->r[1]; rdx = c->r[2]; rbx = c->r[3]; rsp = c->r[4]; \
  rbp = c->r[5]; rsi = c->r[6]; rdi = c->r[7]; r8 = c->r[8]; r9 = c->r[9]; r10 = c->r[10]; \
  r11 = c->r[11]; r12 = c->r[12]; r13 = c->r[13]; r14 = c->r[14]; r15 = c->r[15]; XFILL(); } while (0)
#define SPILL() do { c->r[0] = rax; c->r[1] = rcx; c->r[2] = rdx; c->r[3] = rbx; c->r[4] = rsp; \
  c->r[5] = rbp; c->r[6] = rsi; c->r[7] = rdi; c->r[8] = r8; c->r[9] = r9; c->r[10] = r10; \
  c->r[11] = r11; c->r[12] = r12; c->r[13] = r13; c->r[14] = r14; c->r[15] = r15; XSPILL(); } while (0)

// Register traffic around calls. By default every guest register goes
// through rc_ctx at each call and return (exact for any code). With
// RC_ABI_TRUST the generated code assumes callees follow the SysV ABI, as
// compiler-generated code does: a call passes argument and callee-saved
// registers and gets back rax/rdx/xmm0/xmm1 (callee-saved ones come back
// unchanged, rsp is restored by the callee's ret).
#ifdef RC_ABI_TRUST
#define SPILL_CALL() do { c->r[0] = rax; c->r[1] = rcx; c->r[2] = rdx; c->r[3] = rbx; c->r[4] = rsp; \
  c->r[5] = rbp; c->r[6] = rsi; c->r[7] = rdi; c->r[8] = r8; c->r[9] = r9; c->r[12] = r12; \
  c->r[13] = r13; c->r[14] = r14; c->r[15] = r15; c->x[0] = x0; c->x[1] = x1; c->x[2] = x2; \
  c->x[3] = x3; c->x[4] = x4; c->x[5] = x5; c->x[6] = x6; c->x[7] = x7; } while (0)
#define FILL_CALL() do { rax = c->r[0]; rdx = c->r[2]; x0 = c->x[0]; x1 = c->x[1]; rsp += 8; } while (0)
#define SPILL_RET() do { c->r[0] = rax; c->r[2] = rdx; c->r[4] = rsp; c->x[0] = x0; c->x[1] = x1; } while (0)
#else
#define SPILL_CALL() SPILL()
#define FILL_CALL() FILL()
#define SPILL_RET() SPILL()
#endif

// Integer/pointer-only native call through a bound import slot.
static inline uint64_t rc_native6(uint64_t fn, uint64_t a, uint64_t b, uint64_t c_, uint64_t d,
                                  uint64_t e, uint64_t f) {
  return ((uint64_t(*)(uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t))fn)(a, b, c_, d, e, f);
}

#endif
